package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's claimed-total
 * and due-total. A change takes them before it writes, then {@link #record} audits the ones it moved: a ROLLUP line
 * per person whose figures changed (in the order they were added; a new person counts as changed), then a TOTALS
 * line when the sheet's totals changed.
 */
@Service
public class Rollup {

    /** A person's figures: claimed (two decimals) and due-total (two decimals, or n/a). */
    public record Figures(String name, String claimed, String dueTotal) {
    }

    /** The sheet's figures at one moment: per person id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
    }

    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final SheetClock clock;
    private final Settings settings;
    private final Audit audit;

    public Rollup(People people, Claims claims, Rates rates, SheetClock clock, Settings settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.clock = clock;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures now. */
    public Snapshot take(String sheet) {
        LocalDate today = clock.today(sheet);
        List<Rate> sheetRates = rates.list(sheet);
        BigDecimal floor = settings.floor(sheet);
        Late late = settings.late(sheet, today);
        List<Claim> all = claims.list(sheet);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheet)) {
            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && c.counts(person.held())).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            for (Claim claim : mine) {
                claimed = claimed.add(new BigDecimal(claim.amount()));
                BigDecimal d = claim.due(sheetRates, person.grade(), floor, late);
                due = d == null ? due : due.add(d);
            }
            // n/a when the grade has no rate on the sheet's today, unless a claim keeps a figure.
            boolean na = Rate.on(sheetRates, person.grade(), today) == null && mine.stream().noneMatch(Claim::fixed);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString()));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
    public void record(String sheet, String user, Snapshot before) {
        Snapshot after = take(sheet);
        String prefix = " sheet=" + sheet + " by=" + user + " ";
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal());
            }
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the status the change takes it to, refusing a change its status does not allow. */
public class ApplyClaimStatus {
    public void apply(@PathVariable("sheet") String sheet, @PathVariable("change") String change,
            @RequestParam("user") String user, @Val Claim claim, Claims claims, People people, Rates rates, Periods periods,
            Roles roles, Settings settings, SheetClock clock, Audit audit, Rollup rollup)
            throws InvalidClaimStatusChangeException {
        ClaimStatusChange requested = ClaimStatusChange.of(change);
        if (requested == null) {
            throw new InvalidClaimStatusChangeException("No such status change: " + change);
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot change status");
        }
        // Four eyes: the user who opened a claim may not settle it.
        if (requested == ClaimStatusChange.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle it");
        }
        Person person = people.find(sheet, claim.person());
        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit);
        // a steward settles anything.
        if (requested == ClaimStatusChange.SETTLE && Role.CLERK.equals(roles.of(sheet, user))) {
            BigDecimal limit = settings.clerkLimit(sheet);
            BigDecimal due = claim.due(rates.list(sheet), person.grade(), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                throw new InvalidClaimStatusChangeException("A clerk cannot settle a due above the clerk limit");
            }
        }
        Rollup.Snapshot before = rollup.take(sheet);
        ClaimStatus next = claim.status().after(requested);
        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // Opening gives the sheet's next number; a voided claim keeps the number it had (never reused).
        Claim changed = claim;
        if (requested == ClaimStatusChange.OPEN) {
            changed = claim.withNumber(claims.nextNumber(sheet));
            claims.setNumber(sheet, claim.id(), changed.number());
            claims.setOpenedBy(sheet, claim.id(), user);
        }
        String fields = changed.statusAuditFields(person.name());
        // Settling fixes the due at the person's grade rate in force on the claim's date (or the figure its
        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
        if (requested == ClaimStatusChange.SETTLE) {
            BigDecimal due = claim.due(rates.list(sheet), person.grade(), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            claims.setSettledDue(sheet, claim.id(), due);
            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
        }
        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Takes a statement of the person: records their due-total now (late charges included), binds each of their
 * counting claims to the figure it has now (without its late charge) and unbinds the rest. The due-total is n/a
 * when their grade has no rate on the sheet's today, unless a
 * counting claim keeps a figure (settled or bound): then it is the figures there are.
 */
public class TakeStatement {
    public void take(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            Claims claims, Rates rates, Statements statements, SheetClock clock, Settings settings, Audit audit,
            Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        LocalDate today = clock.today(sheet);
        List<Rate> sheetRates = rates.list(sheet);
        BigDecimal floor = settings.floor(sheet);
        Late late = settings.late(sheet, today);
        List<Claim> mine = claims.list(sheet).stream().filter((c) -> c.person() == person.id()).toList();
        boolean na = Rate.on(sheetRates, person.grade(), today) == null
                && mine.stream().noneMatch((c) -> c.counts(person.held()) && c.fixed());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int count = 0;
        for (Claim claim : mine) {
            if (claim.counts(person.held())) {
                // The statement binds the figure; the late charge keeps following the sheet's today.
                claims.setStated(sheet, claim.id(), true, claim.figure(sheetRates, person.grade(), floor));
                BigDecimal due = claim.due(sheetRates, person.grade(), floor, late);
                total = due == null ? total : total.add(due);
                count++;
            } else if (claim.stated()) {
                claims.setStated(sheet, claim.id(), false, null);
            }
        }
        BigDecimal dueTotal = na ? null : total;
        statements.add(sheet, person.id(), dueTotal, today);
        audit.record("STATEMENT sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
                + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
        rollup.record(sheet, user, before);
    }
}
