import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Closes the period, fixing its due-total now: the due of the counted (OPEN and SETTLED, but not a held person's
 * OPEN) claims dated in it (a
 * claim with no rate adds nothing). Refuses a period not on the sheet or already closed.
 */
public class ClosePeriod {
    public void close(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
            @RequestParam("user") String user, Periods periods, Claims claims, People people, Rates rates, Settings settings,
            SheetClock clock, Audit audit)
            throws InvalidPeriodException {
        Period found = periods.find(sheet, period);
        if (found == null) {
            throw new InvalidPeriodException("There is no period named " + period);
        }
        if (found.closed()) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Rate> sheetRates = rates.list(sheet);
        BigDecimal floor = settings.floor(sheet);
        Late late = settings.late(sheet, clock.today(sheet));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.list(sheet)) {
            LocalDate date = LocalDate.parse(claim.date());
            Person person = byId.get(claim.person());
            if (person == null || !claim.counts(person.held()) || date.isBefore(from) || date.isAfter(to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.grade(), floor, late);
            total = due == null ? total : total.add(due);
        }
        if (!periods.close(sheet, period, total)) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
        audit.record("PERIOD_CLOSED sheet=" + sheet + " by=" + user + " period=" + period + " total="
                + total.toPlainString());
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The sheet's "today". Every date decision and every default date in the app reads the date from
 * here, never from the real clock. A sheet starts at the real date until its today is set.
 */
@Service
public class SheetClock {

    private final JdbcTemplate jdbc;

    public SheetClock(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public LocalDate today(String sheet) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getDate(1).toLocalDate(), sheet);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheet, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheet, Date.valueOf(today));
    }
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.DuplicatePersonNameException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The person on the sheet with the typed name (ignoring case), else a new one of grade A. */
public class ResolveQuickAddPerson {
    public void resolve(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val QuickAddRequest request, People people, Audit audit, Rollup rollup, Out<Person> person)
            throws DuplicatePersonNameException {
        Person found = people.findByName(sheet, request.name());
        if (found != null) {
            person.set(found);
            return;
        }
        Rollup.Snapshot before = rollup.take(sheet);
        Person added = people.add(sheet, request.name(), "A");
        person.set(added);
        audit.record("PERSON_ADDED sheet=" + sheet + " by=" + user + " name=" + added.name() + " grade="
                + added.grade());
        rollup.record(sheet, user, before);
    }
}
    /**
     * This claim's due: its {@link #figure} plus, while it is overdue, its late charge (settling fixes the charge
     * in); null when there is no figure.
     */
    public BigDecimal due(List<Rate> rates, String grade, BigDecimal floor, Late late) {
        BigDecimal figure = figure(rates, grade, floor);
        return figure == null || settledDue != null ? figure : figure.add(late.charge(this, figure));
    }

    /**
     * This claim's figure: the due fixed when settled, else the one its statement bound, else its amount at the
     * grade's rate in force on its date, raised to at least the sheet's floor; null when there is none.
     */
    public BigDecimal figure(List<Rate> rates, String grade, BigDecimal floor) {
        if (settledDue != null) {
            return new BigDecimal(settledDue);
        }
        if (stated) {
            return statedDue == null ? null : new BigDecimal(statedDue);
        }
        BigDecimal live = Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)));
        return live == null ? null : live.max(floor);
    }
}

