import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Grade } from '../people/people';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-MM-dd; null when it
 *  applies from the beginning of time). */
export type Rate = { grade: Grade; pct: string; from: string | null };

export const ratesKey = (sheet: string) => ['rates', sheet] as const;

export const ratesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;

/** Every rate on the sheet, by grade then from-date (the one with none first); a grade with no rate is absent. */
export function useRates(sheet: string) {
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(ratesPath(sheet)),
  });
}

/** The rate for a grade on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it, or
 *  undefined when the date is before every rate the grade has (or the date is not yet known). */
export function rateOf(rates: Rate[], grade: Grade, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.pct;
}

/** A two-decimal string as a whole number of hundredths. */
export function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.split('.');
  if (figure === undefined || claim.settledDue !== null) return figure;
  return figure + lateCents(claim, figure, late);
}


/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
 *  has no rate on the sheet's today, unless a settled or stated claim keeps a figure: then the figures there are. */
export function personDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  today: string | undefined,
  floor: bigint,
  late: Late,
): bigint | undefined {
  const mine = counted(claims.filter((c) => c.person === person.id), [person]);
  if (rateOf(rates, person.grade, today) === undefined && !mine.some(fixed)) return undefined;
  return mine.reduce((sum, c) => sum + (claimDueCents(c, rateOf(rates, person.grade, c.date), floor, late) ?? 0n), 0n);
}

/** A claim's due-by (yyyy-MM-dd): its date plus the sheet's terms in days. */
export function dueBy(claim: Claim, terms: number): string {
  const d = new Date(`${claim.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: OPEN with its due-by before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string | undefined): boolean {
  return claim.status === 'OPEN' && today !== undefined && dueBy(claim, terms) < today;
}

/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
 *  their dues (in hundredths; a claim with no due adds nothing). */
export function overdueCents(
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  late: Late,
  floor: bigint,
): { count: number; cents: bigint } {
  const grades = new Map(people.map((p) => [p.id, p.grade]));
  const overdueClaims = counted(claims, people).filter((c) => grades.has(c.person) && overdue(c, late.terms, late.today));
  const cents = overdueClaims.reduce(
    (sum, c) => sum + (claimDueCents(c, rateOf(rates, grades.get(c.person)!, c.date), floor, late) ?? 0n),
    0n,
  );
  return { count: overdueClaims.length, cents };
}

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    send(draft);
  };

  const grades = new Map(people.map((p) => [p.id, p.grade]));
  const totals = new Map<string, bigint>();
  for (const c of counted(all, people)) {
    const period = periodOf(periods, c.date);
    const grade = grades.get(c.person);
    if (period === undefined || grade === undefined) continue;
    const due = claimDueCents(c, rateOf(rates, grade, c.date), floor, late) ?? 0n;
    totals.set(period.name, (totals.get(period.name) ?? 0n) + due);
  }

  return (
    <section>
      <h2>Periods</h2>
      <form onSubmit={submit}>
        <label>

// One claim with its status and the buttons that change it. Every button is offered; the server
// refuses a change the claim's status does not allow, and the row shows that error until its next action.
function ClaimRow({ sheet, user, claim, rates, grade, editing, onEdit, onCancel }: {
  sheet: string;
  user: string;
  claim: Claim;
  rates: Rate[];
  grade: Grade;
  editing: boolean;
  onEdit: () => void;
          <input
            data-testid="claim-form-amount"
            placeholder="amount"
            value={draft.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-date"
            placeholder="yyyy-mm-dd"
            value={draft.date}
            onChange={(e) => change({ date: e.target.value })}
          />{' '}
          <input
            data-testid="claim-form-note"
            placeholder="note"
            value={draft.note}
            onChange={(e) => change({ note: e.target.value })}
          />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {save.isError && (
            <span data-testid="claim-form-error" role="alert">
              {' '}A claim needs an amount of 0.00 or more with up to two decimals, and a valid date not after the person's retirement date; only a DRAFT claim can be edited.
            </span>
          )}
        </form>
        <ul>
          {claims.map((c) => (
            <ClaimRow
              key={c.id}
              sheet={sheet}
              user={user}
              claim={c}
              rates={rates}
              grade={person.grade}
              editing={editing === c.id}
              onEdit={() => open(c)}
              onCancel={cancel}
            />
          ))}
        </ul>
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 10, Component: ClaimedHeader }),
  PersonColumns.fill({ order: 10, Component: PersonClaims }),
];

